        let event = contract.GetEventBySignature("0x28e768db988d672e663e2b8b912bdb41f84665306f64258da011c8a42125eb83")
        for log in logs do
            if String.Equals(log.Address, contract.Address, StringComparison.OrdinalIgnoreCase) && event.IsLogForEvent(log) then
                result.Add(EventLog<DepositedEvent>(decodeDepositedEvent contract log, log))
        return result
    }

